package Ref;
use strict; use warnings;
sub cport {
  my ($s)=@_;
  if ($s =~ /\A[\x09\x0A\x0B\x0C\x0D\x20]*([+-]?)([0-9]+)/) {
    my ($sg,$d)=($1,$2);
    my $mag=$d; $mag =~ s/\A0+(?=[0-9])//;
    return -1 if length($mag) > 5;
    my $v = 0+$mag;
    $v = -$v if $sg eq '-';
    return -1 if $v < 0 || $v > 65535;
    return $v;
  }
  return -1;
}
sub parse {
  my ($url)=@_;
  my ($scheme,$host,$port,$path,$query)=('','',-1,'','');
  my $rest=$url;
  my $hp=index($rest,"#");
  $rest=substr($rest,0,$hp) if $hp>=0;
  my $qp=index($rest,"?");
  if ($qp>=0){ $query=substr($rest,$qp+1); $rest=substr($rest,0,$qp); }
  my $sp=index($rest,"://");
  if ($sp<0){ $path=$rest; return ($scheme,$host,$port,$path,$query); }
  $scheme=substr($rest,0,$sp); $scheme =~ tr/A-Z/a-z/;
  $rest=substr($rest,$sp+3);
  my $sl=index($rest,"/");
  my $auth;
  if ($sl>=0){ $auth=substr($rest,0,$sl); $path=substr($rest,$sl); }
  else { $auth=$rest; }
  my $at=index($auth,"\@");
  $auth=substr($auth,$at+1) if $at>=0;
  my $c=index($auth,":");
  if ($c<0){ $host=$auth; return ($scheme,$host,$port,$path,$query); }
  $host=substr($auth,0,$c);
  $port=cport(substr($auth,$c+1));
  return ($scheme,$host,$port,$path,$query);
}
1;
